SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS concert_archive_concerts (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    concert_key CHAR(40) NOT NULL,
    concert_date DATE NULL,
    name VARCHAR(512) NOT NULL,
    source_url VARCHAR(1024) NULL,
    venue_name VARCHAR(255) NULL,
    venue_address VARCHAR(512) NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_concert_key (concert_key),
    KEY idx_concert_date (concert_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS concert_archive_performers (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    performer_key CHAR(40) NOT NULL,
    name VARCHAR(512) NOT NULL,
    performer_type VARCHAR(64) NULL,
    source_url VARCHAR(1024) NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_performer_key (performer_key),
    KEY idx_performer_name (name(191))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS concert_archive_concert_performers (
    concert_id BIGINT UNSIGNED NOT NULL,
    performer_id BIGINT UNSIGNED NOT NULL,
    PRIMARY KEY (concert_id, performer_id),
    CONSTRAINT fk_ca_concert FOREIGN KEY (concert_id)
        REFERENCES concert_archive_concerts(id) ON DELETE CASCADE,
    CONSTRAINT fk_ca_performer FOREIGN KEY (performer_id)
        REFERENCES concert_archive_performers(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

